import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`hvac-estimate`,heroTitle:`Generate HVAC estimates in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded plans, sizes the equipment and labor, and delivers an HVAC estimate automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your HVAC plans`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded HVAC plans, takeoffs, or project notes. Build a complete HVAC estimate. (1) Extract the building scope, units, zones, equipment needs, ductwork requirements, and installation constraints from the uploaded files. (2) Estimate equipment, materials, labor hours, subcontractor work, and startup or commissioning needs. (3) Build pricing options with assumptions, alternates, and margin. (4) Highlight any dependencies, exclusions, or field-verification items that should be confirmed before sending. (5) Deliver a client-ready HVAC estimate with line-item costs, scope summary, and next steps.`,heroOverlaySteps:[`Extracting zones, equipment needs, and installation scope from your files`,`Sizing equipment, materials, labor, and subcontractor work`,`Building pricing options with assumptions, alternates, and exclusions`,`Client-ready HVAC estimate with scope summary, ready to send`],generatingSteps:[`Reading the uploaded plans, takeoffs, and job notes`,`Designing an agent to organize equipment, labor, and material requirements`,`Configuring estimate logic for alternates, assumptions, and margin`,`Preparing a detailed HVAC estimate with line items and next steps`],featureSectionTitle:`From plans to install-ready estimate`,featureCardTitles:[`Connects to your estimating workflow`,`Estimates built for field reality`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, sheets, takeoffs, and internal estimating workflows stay connected so review and revisions move faster.`,`Equipment lists. Labor assumptions. Alternates. Exclusions. Computer gives your team an HVAC estimate draft that is ready for client review.`],capabilitySectionTitle:`Your estimator, on autopilot`,capabilitySectionSubtitle:`Upload the plans, get back an HVAC estimate built around the real install scope.`,capabilityCards:[{title:`Plan Analysis`,description:`Computer can extract zones, equipment, ductwork, controls, and install constraints from HVAC plans, takeoffs, and job notes.`},{title:`Equipment & Labor Pricing`,description:`Computer can size equipment, materials, and labor hours so your estimate reflects the actual scope instead of a generic template.`},{title:`Option Builder`,description:`Computer can assemble alternates, assumptions, exclusions, and pricing options so you can send a clearer quote with less manual work.`},{title:`Connect Your Tools`,description:`Computer can organize estimate drafts across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Standards`,description:`Computer can remember your preferred equipment vendors, markup rules, and estimate structure across sessions so quotes stay consistent.`},{title:`Revision Support`,description:`Computer can update the estimate when scope changes, new equipment options appear, or field conditions shift after the first draft.`}]});export{t as default};
